import json,pathlib,socket,struct,subprocess,sys,threading,urllib.request
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
server=None

def run(*args):return subprocess.check_output(args,text=True,timeout=5)

print(json.dumps({'ready':True,'pid':__import__('os').getpid()}),flush=True)
try:
 for line in sys.stdin:
  data=json.loads(line)
  try:
   op=data['op']
   if op=='serve':
    content=data['content'].encode()
    class Handler(BaseHTTPRequestHandler):
     def log_message(self,*args):pass
     def do_GET(self):
      self.send_response(200);self.send_header('Content-Length',str(len(content)));self.end_headers();self.wfile.write(content)
    server=ThreadingHTTPServer(('0.0.0.0',18080),Handler);threading.Thread(target=server.serve_forever,daemon=True).start();result=True
   elif op=='http':
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
    with opener.open('http://'+data['address']+':18080/',timeout=2) as response:result=response.read().decode()
   elif op=='announce':
    iface=data['interface'];mac=bytes.fromhex(json.loads(run('ip','-j','link','show','dev',iface))[0]['address'].replace(':',''))
    address=socket.inet_aton(data['address']);packet=b'\xff'*6+mac+struct.pack('!H',0x0806)+struct.pack('!HHBBH',1,0x0800,6,4,1)+mac+address+b'\x00'*6+address
    with socket.socket(socket.AF_PACKET,socket.SOCK_RAW,socket.htons(0x0806)) as link:link.bind((iface,0));link.send(packet)
    result=True
   else:raise ValueError('unknown trusted worker operation')
   print(json.dumps({'ok':True,'result':result}),flush=True)
  except Exception as exc:print(json.dumps({'ok':False,'error':type(exc).__name__+': '+str(exc)}),flush=True)
finally:
 if server is not None:server.shutdown();server.server_close()
